  ('Legal & Compliance', 'business', 'Contracts, notices and rules in plain words.', 'names, dates and what was agreed', 'a ready legal document', 'document', NULL, NULL),
  ('Operations & Inventory', 'business', 'Stock, shifts, repairs and quality checks.', 'your stock or task list', 'a sheet that adds up for you', 'sheet', 'the order or job details', 'a ready document to print'),
  ('HR & Staffing', 'business', 'Hire people, track attendance and pay salaries.', 'your staff details', 'a filled sheet or document', 'sheet', 'the employee''s details', 'a ready letter or form'),
