INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('business-plan-studio', 'Business Plan Studio', 'Answer a few guided questions and get a lender-ready business plan with market, operations, 3-year projections and risks.', 'Startups & Strategy', ARRAY['Planning', 'Document Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('pitch-deck-builder', 'Pitch Deck Builder', 'Turn a one-page brief into a 12-slide investor pitch deck with slide text, speaker notes and design direction for each slide.', 'Startups & Strategy', ARRAY['Presentations', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('investor-q-a-rehearsal', 'Investor Q&A Rehearsal', 'Practise your pitch with a tough AI investor who asks real questions, scores every answer and gives you a prep sheet.', 'Startups & Strategy', ARRAY['Coaching', 'Presentations'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('competitor-teardown', 'Competitor Teardown', 'Paste what you know about 3 to 5 rivals and get a feature grid, pricing map, positioning and the gaps you can win.', 'Startups & Strategy', ARRAY['Research', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Marketing & Sales']),
  ('market-sizing-lab', 'Market Sizing Lab', 'Work out TAM, SAM and SOM top-down and bottom-up, with every assumption shown and what changes if you are wrong.', 'Startups & Strategy', ARRAY['Research', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('franchise-readiness-check', 'Franchise Readiness Check', 'Score your business on unit economics, systems and brand, then get a franchise model, fee structure and launch steps.', 'Startups & Strategy', ARRAY['Planning', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('unit-economics-doctor', 'Unit Economics Doctor', 'Upload a P&L or type your numbers to get CAC, LTV, contribution margin and a ranked list of fixes that grow profit.', 'Startups & Strategy', ARRAY['Analytics Tools', 'Finance & Billing'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('business-model-canvas-coach', 'Business Model Canvas Coach', 'Fill all nine blocks of the business model canvas with a coach who questions each one and ends with a lean test plan.', 'Startups & Strategy', ARRAY['Coaching', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('government-scheme-finder', 'Government Scheme Finder', 'Match your business to central and state schemes, subsidies and loans, with eligibility checklists and steps for each.', 'Startups & Strategy', ARRAY['Research', 'Finance & Billing'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('due-diligence-pack', 'Due Diligence Pack', 'Upload a company''s documents to get a red-flag report, missing-documents list and the questions to ask before you invest or buy.', 'Startups & Strategy', ARRAY['Legal & Compliance', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance']),
  ('board-meeting-pack', 'Board Meeting Pack', 'Turn this month''s numbers and updates into a board deck outline, KPI dashboard, decisions needed and a minutes draft.', 'Startups & Strategy', ARRAY['Presentations', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('sop-builder', 'SOP Builder', 'Explain a process by voice or text and get step-by-step SOPs with checklists, quality checks and a training quiz.', 'Startups & Strategy', ARRAY['Operations', 'Document Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Operations & Inventory']),
  ('employee-handbook-writer', 'Employee Handbook Writer', 'Answer questions about your company and get a full employee handbook covering culture, policies, leave and conduct.', 'Startups & Strategy', ARRAY['HR & Staffing', 'Document Tools'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
  ('pricing-strategy-lab', 'Pricing Strategy Lab', 'Use your costs, rival prices and customer types to build price tiers, a launch offer and a margin chart you can trust.', 'Startups & Strategy', ARRAY['Planning', 'Finance & Billing'], 'featured', true, false, false, NULL, 0, ARRAY['Marketing & Sales']),
  ('customer-interview-analyser', 'Customer Interview Analyser', 'Upload customer interview recordings or transcripts to get themes, ranked pain points, quotes and persona cards.', 'Startups & Strategy', ARRAY['Research', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('product-requirements-studio', 'Product Requirements Studio', 'Turn a product idea into a full PRD with user stories, flows, acceptance criteria, metrics and a phased release plan.', 'Startups & Strategy', ARRAY['Planning', 'Developer Tools'], 'featured', true, false, false, NULL, 0, ARRAY['AI Agent']),
  ('okr-planner', 'OKR Planner', 'Turn company goals into measurable OKRs for each team, with a weekly check-in tracker and a quarter-end review template.', 'Startups & Strategy', ARRAY['Planning', 'Productivity'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
  ('business-valuation-estimator', 'Business Valuation Estimator', 'Value a business three ways from its financials, with a range, the assumptions behind it and a short buyer memo.', 'Startups & Strategy', ARRAY['Finance & Billing', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('restaurant-launch-planner', 'Restaurant Launch Planner', 'Take a restaurant or café concept to menu costing, licence checklist, launch budget and an opening-week marketing plan.', 'Startups & Strategy', ARRAY['Planning', 'Operations'], 'featured', true, false, false, NULL, 0, ARRAY['Operations & Inventory']),
  ('annual-report-maker', 'Annual Report Maker', 'Turn a year''s numbers, highlights and photos into a polished annual or impact report for an SME, NGO or trust.', 'Startups & Strategy', ARRAY['Document Tools', 'Presentations'], 'featured', true, false, false, NULL, 0, '{}'::text[])
